using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Threading.Tasks;using System.Runtime.InteropServices;
class CleanupFlowRegression {
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr CreateDesktop(string n,IntPtr a,IntPtr b,uint c,uint access,IntPtr d);
 [DllImport("user32.dll")]static extern bool SetThreadDesktop(IntPtr d);
 static FieldInfo F(string n){return typeof(ClientForm).GetField(n,BindingFlags.NonPublic|BindingFlags.Instance);}
 static void Run(ClientForm c,string n,params object[] args){System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());File.AppendAllText(Path.Combine(Files.DirectoryPath,"..","flow-trace.txt"),"Before "+n+"\n");var t=typeof(ClientForm).GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(c,args) as Task;if(t!=null){while(!t.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(10);}t.GetAwaiter().GetResult();}File.AppendAllText(Path.Combine(Files.DirectoryPath,"..","flow-trace.txt"),"After "+n+"\n");}
 static Dictionary<string,object> State(string id,bool admin){return Files.Json.Deserialize<Dictionary<string,object>>("{\"stationName\":\"Teste\",\"serverNow\":1,\"last\":null,\"adminAccess\":"+(admin?"{\"username\":\"admin\"}":"null")+",\"active\":"+(id==null?"null":"{\"id\":\""+id+"\",\"memberName\":\"Teste\",\"remainingSeconds\":300}")+"}");}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 [STAThread]static int Main(string[] args){int code=1;var desktop=CreateDesktop("CleanupFlow"+Guid.NewGuid().ToString("N"),IntPtr.Zero,IntPtr.Zero,0,0x10000000,IntPtr.Zero);var thread=new System.Threading.Thread(()=>{try{if(desktop==IntPtr.Zero||!SetThreadDesktop(desktop))throw new Exception("Desktop isolado indisponível");string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Files.DirectoryPath=Path.Combine(root,"ClientConfig");var processes=new List<CleanupProcess>();bool deny=false;var cleaner=new SessionCleanup(Path.Combine(root,"Client"),Path.Combine(root,"Local"),Path.Combine(root,"Roaming"),()=>new List<CleanupProcess>(processes),p=>{if(deny)throw new IOException("Teste bloqueado");processes.RemoveAll(x=>x.Key==p.Key);});var c=new ClientForm(new Settings{stationName="Teste",server="https://127.0.0.1:3443",fingerprint=new string('0',64),token=new string('0',64)},true);{foreach(string f in new[]{"applyPolicies","restorePolicies","saveSettings"})F(f).SetValue(c,new Action<Settings>(s=>{}));F("sessionCleanup").SetValue(c,cleaner);c.Show();Application.DoEvents();System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());
 Run(c,"ApplyClean",State("a",false));Check(cleaner.Pending,"Member not tracked");processes.Add(new CleanupProcess{pid=10,started=1,name="game",visible=true});cleaner.Observe();deny=true;try{Run(c,"ApplyClean",State(null,false));throw new Exception("Failure expected");}catch(IOException){}Check((bool)F("cleanupBlocked").GetValue(c),"Failure did not block");Run(c,"RefreshClock");Check((bool)F("locked").GetValue(c),"Desktop exposed");Check(!((Button)F("login").GetValue(c)).Enabled,"Login exposed");deny=false;Run(c,"ApplyClean",State(null,false));Check(!cleaner.Pending&&processes.Count==0,"Finish failed");
 Run(c,"ApplyClean",State("b",false));processes.Add(new CleanupProcess{pid=11,started=2,name="game",visible=true});Run(c,"ApplyClean",State(null,true));Check(!cleaner.Pending&&processes.Count==0,"Maintenance failed");Run(c,"ApplyClean",State(null,false));Check(!cleaner.Pending,"Admin logout starts cleanup");
 Run(c,"ApplyClean",State("c",false));processes.Add(new CleanupProcess{pid=12,started=3,name="game",visible=true});((TimeBudget)F("budget").GetValue(c)).Update("c",0,0);Run(c,"RefreshClock");var until=DateTime.UtcNow.AddSeconds(10);while((cleaner.Pending||F("cleanupTask").GetValue(c)!=null)&&DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}Check(!cleaner.Pending&&processes.Count==0,"Local expiry failed");F("allowedExit").SetValue(c,true);c.Close();}File.WriteAllText(args[1],"PASS: fim remoto/manual, expiração local, manutenção, administração, falha bloqueia e nova tentativa libera. Desktop isolado; nenhuma política real modificada.");code=0;}catch(Exception e){File.WriteAllText(args[1],e.ToString());}});thread.SetApartmentState(System.Threading.ApartmentState.STA);thread.Start();thread.Join();return code;}
}
